#include <vector>
#include <algorithm>

class Solution {
public:
    long long minInversionsPrefixTree(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;

        long long total_inv = 0;
        std::vector<std::vector<int>> groups = {nums};

        for (int bit = 29; bit >= 0; --bit) {
            long long inv01 = 0, inv10 = 0;
            std::vector<std::vector<int>> next_groups;

            for (auto const& grp : groups) {
                int c0 = 0, c1 = 0;
                std::vector<int> g0, g1;
                for (int x : grp) {
                    if ((x >> bit) & 1) {
                        inv01 += c0;
                        c1++;
                        g1.push_back(x);
                    } else {
                        inv10 += c1;
                        c0++;
                        g0.push_back(x);
                    }
                }
                if (!g0.empty()) next_groups.push_back(g0);
                if (!g1.empty()) next_groups.push_back(g1);
            }
            total_inv += std::min(inv01, inv10);
            groups = next_groups;
        }
        return total_inv;
    }
};

import java.util.*;

class Solution {
    public long minInversionsPrefixTree(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;

        long totalInv = 0;
        List<int[]> groups = new ArrayList<>();
        groups.add(nums);

        for (int bit = 29; bit >= 0; bit--) {
            long inv01 = 0, inv10 = 0;
            List<int[]> nextGroups = new ArrayList<>();

            for (int[] grp : groups) {
                int c0 = 0, c1 = 0;
                List<Integer> g0 = new ArrayList<>();
                List<Integer> g1 = new ArrayList<>();
                for (int x : grp) {
                    if (((x >> bit) & 1) == 1) {
                        inv01 += c0;
                        c1++;
                        g1.add(x);
                    } else {
                        inv10 += c1;
                        c0++;
                        g0.add(x);
                    }
                }
                if (!g0.isEmpty()) {
                    int[] a0 = new int[g0.size()];
                    for (int i = 0; i < g0.size(); i++) a0[i] = g0.get(i);
                    nextGroups.add(a0);
                }
                if (!g1.isEmpty()) {
                    int[] a1 = new int[g1.size()];
                    for (int i = 0; i < g1.size(); i++) a1[i] = g1.get(i);
                    nextGroups.add(a1);
                }
            }
            totalInv += Math.min(inv01, inv10);
            groups = nextGroups;
        }
        return totalInv;
    }
}

